def char_to_value(c):
    if c.isdigit():
        return int(c)
    else:
        return ord(c.upper()) - ord('A') + 10

def value_to_char(v):
    if v < 10:
        return str(v)
    else:
        return chr(ord('A') + v - 10)

def str_to_decimal(s, radix):
    total = 0
    for c in s:
        total = total * radix + char_to_value(c)
    return total

def decimal_to_str(n, radix):
    if n == 0:
        return '0'
    digits = []
    while n > 0:
        remainder = n % radix
        digits.append(value_to_char(remainder))
        n = n // radix
    return ''.join(reversed(digits))

